app = rep(app, "<button type=\"button\" onClick={() => void copyPlaylist(playlist.id)}>Kopieren</button><button type=\"button\" onClick={() => void sharePlaylist(playlist.id)}>Teilen</button>", "<button type=\"button\" onClick={() => copyPlaylist(playlist.id)}>Kopieren</button><button type=\"button\" disabled={!clipboard} onClick={() => pasteFromPlaylistMenu(playlist.id)}>Einfügen</button><button type=\"button\" onClick={() => openTagChooser('playlist', [playlist.id])}>Tags</button><button type=\"button\" onClick={() => void sharePlaylist(playlist.id)}>Teilen</button>", 'playlist menu copy paste tags')
app = rep(app, "{overflowMenu.kind === 'playlists' && <><button type=\"button\" onClick={() => beginReorder('sidebar')}>Bearbeiten</button><button type=\"button\" onClick={() => { setOverflowMenu(null); navigateTo({ view: 'playlistOverview', playlistId: activePlaylistId, detailOpen: false }) }}>Übersicht</button></>}", "{overflowMenu.kind === 'playlists' && <><button type=\"button\" onClick={() => beginReorder('sidebar')}>Bearbeiten</button><button type=\"button\" onClick={() => { setOverflowMenu(null); navigateTo({ view: 'playlistOverview', playlistId: activePlaylistId, detailOpen: false }) }}>Übersicht</button></>}{overflowMenu.kind === 'tags' && <button type=\"button\" onClick={() => beginReorder('tags')}>Bearbeiten</button>}{overflowMenu.kind === 'tag' && overflowMenu.id && (() => { const tag = tags.find((item) => item.id === overflowMenu.id); if (!tag) return null; return <><button type=\"button\" onClick={() => beginRename('tag', tag.id)}>Umbenennen</button><button className=\"danger-menu-action\" type=\"button\" onClick={() => { setTagToDelete(tag); setOverflowMenu(null) }}>Löschen</button></> })()}", 'tag overflow menus')

# Add tag chooser and duplicate conflict before loop confirmations.
anchor = "    {loopConfirmation === 'save' && editorSong && <div className=\"modal-backdrop\""
insert = """    {tagChooserTarget && <div className=\"playlist-chooser-backdrop tag-chooser-backdrop\" onMouseDown={() => setTagChooserTarget(null)}><section className=\"playlist-chooser tag-chooser\" onMouseDown={(event) => event.stopPropagation()}><div className=\"playlist-chooser-heading\"><div><p className=\"eyebrow\">TAGS</p><h2>{tagChooserTarget.kind === 'song' ? `${tagChooserTarget.ids.length} ${tagChooserTarget.ids.length === 1 ? 'Lied' : 'Lieder'}` : `${tagChooserTarget.ids.length} ${tagChooserTarget.ids.length === 1 ? 'Playlist' : 'Playlists'}`} taggen</h2></div><button type=\"button\" onClick={() => setTagChooserTarget(null)}>×</button></div><div className=\"tag-chooser-list\">{sidebarTags.map((tag) => { const ids = tagChooserTarget.kind === 'song' ? tag.songIds : tag.playlistIds; const all = tagChooserTarget.ids.every((id) => ids.includes(id)); const some = !all && tagChooserTarget.ids.some((id) => ids.includes(id)); return <button key={tag.id} type=\"button\" onClick={() => void toggleTargetTag(tag)}><span><i className=\"tag-dot\" style={{ background: tag.color }} /><b>{tag.name}</b></span><small>{tag.songIds.filter((id) => songs.some((song) => song.id === id)).length} Lieder</small><strong>{all ? '✓' : some ? '±' : '+'}</strong></button> })}{!sidebarTags.length && <p className=\"tag-empty-hint\">Erstelle zuerst links unter „Tags“ einen Tag.</p>}</div></section></div>}\n\n    {duplicateConflict && <div className=\"modal-backdrop duplicate-conflict-backdrop\" onMouseDown={cancelDuplicateConflict}><div className=\"confirm-dialog\" onMouseDown={(event) => event.stopPropagation()}><h2>Gleicher Name bereits vorhanden</h2><p>{duplicateConflict.names.length === 1 ? `„${duplicateConflict.names[0]}“ ist am Ziel bereits vorhanden.` : `${duplicateConflict.names.length} gleichnamige Einträge sind am Ziel bereits vorhanden.`} Was soll Josi tun?</p><div className=\"dialog-actions duplicate-actions\"><button type=\"button\" onClick={cancelDuplicateConflict}>Abbrechen</button><button type=\"button\" onClick={() => resolveDuplicateConflict('both')}>Beide einfügen</button><button type=\"button\" onClick={() => resolveDuplicateConflict('replace')}>Ersetzen</button></div></div></div>}\n    {tagToDelete && <div className=\"modal-backdrop\" onMouseDown={() => setTagToDelete(null)}><div className=\"confirm-dialog\" onMouseDown={(event) => event.stopPropagation()}><h2>Tag löschen?</h2><p>„{tagToDelete.name}“ wird in den Papierkorb verschoben. Songs und Playlists selbst bleiben erhalten.</p><div className=\"dialog-actions\"><button type=\"button\" onClick={() => setTagToDelete(null)}>Abbrechen</button><button className=\"danger-button\" type=\"button\" onClick={() => void confirmDeleteTag()}>In Papierkorb</button></div></div></div>}\n\n""" + anchor
