# musicDb additions
mdb_path = Path('src/musicDb.ts')
mdb = mdb_path.read_text()
mdb = rep(mdb, "export type Playlist = {\n", "export type Tag = {\n  id: string\n  name: string\n  color: string\n  songIds: string[]\n  playlistIds: string[]\n  createdAt: number\n  lastUsedAt: number\n  sortOrder?: number\n  trashedAt?: number\n}\n\nexport type Playlist = {\n", 'tag type db')
mdb = rep(mdb, "const DB_VERSION = 2\nconst SONGS = 'songs'\nconst SONG_METADATA = 'songMetadata'\nconst PLAYLISTS = 'playlists'\n", "const DB_VERSION = 3\nconst SONGS = 'songs'\nconst SONG_METADATA = 'songMetadata'\nconst PLAYLISTS = 'playlists'\nconst TAGS = 'tags'\n", 'db v3')
mdb = rep(mdb, "      if (!db.objectStoreNames.contains(PLAYLISTS)) db.createObjectStore(PLAYLISTS, { keyPath: 'id' })\n", "      if (!db.objectStoreNames.contains(PLAYLISTS)) db.createObjectStore(PLAYLISTS, { keyPath: 'id' })\n      if (!db.objectStoreNames.contains(TAGS)) db.createObjectStore(TAGS, { keyPath: 'id' })\n", 'tag store')
mdb += """\n\nasync function getAllTags(): Promise<Tag[]> {\n  const db = await openDb()\n  try {\n    const tx = db.transaction(TAGS, 'readonly')\n    return await requestResult(tx.objectStore(TAGS).getAll() as IDBRequest<Tag[]>)\n  } finally { db.close() }\n}\n\nexport async function getTags(): Promise<Tag[]> { return (await getAllTags()).filter((tag) => !tag.trashedAt) }\nexport async function getTrashedTags(): Promise<Tag[]> { return (await getAllTags()).filter((tag) => Boolean(tag.trashedAt)).sort((a, b) => (b.trashedAt ?? 0) - (a.trashedAt ?? 0)) }\n\nexport async function saveTag(tag: Tag): Promise<void> {\n  const db = await openDb()\n  await new Promise<void>((resolve, reject) => {\n    const tx = db.transaction(TAGS, 'readwrite')\n    tx.objectStore(TAGS).put(tag)\n    tx.oncomplete = () => resolve()\n    tx.onerror = () => reject(tx.error)\n    tx.onabort = () => reject(tx.error)\n  })\n  db.close()\n}\n\nexport async function deleteTag(id: string): Promise<void> {\n  const db = await openDb()\n  await new Promise<void>((resolve, reject) => {\n    const tx = db.transaction(TAGS, 'readwrite')\n    tx.objectStore(TAGS).delete(id)\n    tx.oncomplete = () => resolve()\n    tx.onerror = () => reject(tx.error)\n    tx.onabort = () => reject(tx.error)\n  })\n  db.close()\n}\n"""
mdb_path.write_text(mdb)

